style.css:
@-moz-document regexp("^https?://(www|rd)\.vector\.co\.jp/magazine/softnews/.*") {
/* td内、水平（区切り）線用画像前後に改行がない箇所の修正 */
    td > img[alt^="---"] {
        display: block;
        clear: both;
    }

    /* 区切り線前後の余計な改行を非表示 */
    td > img[alt^="---"] + br {
        display: none;
    }

    /* #lib_tab(メニュー)下、tableの無駄な改行を削除 */
    #lib_tab + table br {
        display: none;
    }

    /* 2000年ページ対応（既存CSSから引用） */
    #lib_tab {
        position: absolute;
        top: 240px;
        left: 0;
        width: 1000px;
        text-align: center;
    }

    #lib_tab ul {
        margin: 0;
        padding: 0;
        cursor: default;
    }

    #lib_tab li a,
    #lib_tab li {
        color: #fff;
        display: inline-block;
        display: inline;
        line-height: 23px;
    }

    #lib_tab li a:hover {
        color: #476c31;
    }

    #lib_tab li#current a {
        border-bottom: 3px solid #476c31;
        color: #476c31;
    }

    #lib_tab li:after {
        content: ' - ';
    }

    #lib_tab li:nth-last-child(1):after {
        content: '';
    }

    #lib_tab li a {
        margin: 0 8px;
        text-decoration: none;
        font-size: 12px;
    }

    #lib_tab img {
        display: none;
    }
    
    /* 広告の跡地にメッセージを出す */
    #ad_vectorlarge {
        height: 90px !important;
        width: 728px !important;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        background: #f4f8fb !important; /* 目立ちすぎない非常に薄い水色ベース */
        border: 1px dashed #b0c4de !important; /* スタイリッシュな点線の枠 */
        border-radius: 6px;
        margin: 0 auto !important; /* 中央寄せ */
    }

    /* 既存のGoogle広告の枠自体は非表示 */
    #ad_vectorlarge > div,
    #ad_vectorlarge ins {
        display: none !important;
    }

    /* 表示するテキストの指定 */
    #ad_vectorlarge::after {
        content: "? ベクターソフトレビュー 公開記事アーカイブ ?" !important;
        color: #666666 !important;
        font-weight: bold !important;
        font-size: 14px !important;
        letter-spacing: 1px; /* 文字の間隔を少し広げてスッキリ見せる */
    }
}

@-moz-document url-prefix("https://rd.vector.co.jp/magazine/softnews/"), regexp("^https://www\.vector\.co\.jp/magazine/softnews/(20|98|990[1-3]).*") {
/* 1. v_header：通常時はコンパクトな横長バー */
    #v_header {
        display: block !important;
        position: absolute !important;
        top: 0 !important;
        left: 0 !important;
        width: 320px !important;
        /* 通常時の横幅 */
        height: 25px !important;
        /* 縦幅を半分に */
        overflow: hidden !important;
        opacity: 0.6 !important;
        background: #f8f8f8 !important;
        border: 1px solid #999 !important;
        border-top: none !important;
        border-left: none !important;
        border-radius: 0 0 10px 0;
        z-index: 99999 !important;
        /* 何よりも上に表示 */
        transition: all 0.25s ease-out;
    }

    /* 2. ホバー展開時：1000pxの巨大パネル化 */
    #v_header:hover {
        width: 1045px !important;
        /* ご要望の1000px */
        height: 90px !important;
        /* 中身が十分見える高さ */
        opacity: 1 !important;
        overflow-y: auto !important;
        background: #ffffff !important;
        box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5) !important;
        padding: 10px !important;
    }

    /* 3. 中身の要素が1000pxの中で横に並ぶように調整（展開時のみ） */
    #v_header:hover dl {
        float: left !important;
        margin-right: 20px !important;
        border-right: 1px solid #eee !important;
        padding-right: 20px !important;
    }

    /* 4. メニューとコンテンツの配置（以前のベストを維持） */
    table[align="left"][width="150"] {
        float: left !important;
        margin-right: 20px !important;
        padding-top: 40px !important;
        /* ヘッダーとの干渉回避 */
        position: relative !important;
    }

    center > table {
        margin-left: 180px !important;
        /* 背景とメニューを避ける */
        margin-right: auto !important;
        float: none !important;
        display: block !important;
    }

    /* 広告等の削除 */
    #ad_vectorlarge {
        display: none !important;
    }
}

@-moz-document regexp("^https?://(www|rd)\.vector\.co\.jp/magazine/softnews/97.*") {
/* 97年TABLEタグ対応 body直下、Vectorロゴがあるtableの横幅を調整 */
    body > table:nth-of-type(3){
        width: 610px;
    }
    
    /* td内、一部Vectorロゴの配置修正 */
    td > img[alt^="Vector"]:nth-of-type(2){
        position: relative !important;
        float: left !important;
    }
}
